descriptor.templateCss:
.my-widget {
    font-family: sans-serif;
    padding: 10px;
    background: #f5f5f5;
}

.my-widget h3 {
    margin-top: 0;
}

descriptor.controllerScript:
/* widget controller uses `this` as `vm` */
self.onInit = function () {
    // `self.settings` holds values from your Settings form
    console.log('Initialized widget with label:', self.settings.label);
};

self.onDataUpdated = function () {
    // `self.ctx.data` is an array of your incoming timeseries / latest
    // for demo we'll just pluck raw data values
    self.ctx.data = [];
    if (self.ctx.data && self.ctx.data.length) {
        self.ctx.data.forEach(ds => {
            ds.data.forEach(pt => self.ctx.data.push(pt[1]));
        });
    }
};

self.onResize = function () {
    // handle container resize if needed
};
